"""Author ReadySet's promotional lecture. Existing review remains authoritative."""
import json, shutil
from pathlib import Path
root=Path(__file__).resolve().parents[2]; r=root/'youtube/claude-liam-readyset-show-tell'; r.mkdir(exist_ok=True)
slug=r.name; title='ReadySet: Evidence Before Action'; B=[]
def rem(bid,narr,pattern,props,act='The Useful Idea',**kw):
 b=dict(beat_id=bid,act=act,lane='bookend' if bid in ('BIDEA','BDEFS','BVDT','BHTF','BOUT') else 'remotion',proof_gate='SHOW',narration_text=narr,estimated_duration_s=round(len(narr.split())/2.6,2),voice='am_onyx',engine='kokoro',shot=dict(type='REMOTION',source='own',visual_intent=props.get('title',props.get('caption',pattern)),motion_claim='Reveal the named evidence or process on the narrated cue',show=[{'at':0,'event':'Establish the real artifact or conceptual cast'},{'at':0.25,'event':'Focus the part named by the narration'}],remotion=dict(pattern=pattern,props=props)),**kw);B.append(b);return b
B.append(dict(beat_id='BOPEN',act='Opening',lane='bookend',proof_gate='CARD',narration_text=title+'. See how a research-data comparison becomes an inspectable decision.',estimated_duration_s=8,voice='am_onyx',engine='kokoro',shot=dict(type='CARD',source='own',template='lecture-title-slide-16x9',narration_contract='playlist-title-summary-v1',motion='hold',visual_intent='Approved portrait title card',show=[{'at':0,'event':'Complete title and portrait'}])))
rem('BIDEA','Hallo. This is Liam, in for Bear. ReadySet asks a useful question: what changed in our data, and does that change matter for the analysis we want to run?', 'BrutalistHesitantWriter',dict(text='Did the data change?\nDoes the change matter?',triggerWords='change matter',replacementWords='evidence support action',fontSize=70,charMs=22,hesitateBetween=6,hesitateWithin=1,mistakeRate=2,jitter=20,seed=slug,banner=''),lead_silence_s=.8,qc={'sparse_by_design':True,'sparse_reason':'The framing correction is the visual action.'})
rem('BDEFS','Three terms. A release is one version of the data. A finding is a change supported by evidence. A review is a person deciding what to do with that evidence.','ClaudeDefinitions',dict(title='Terms In This Film',terms=[{'term':'Release','meaning':'One version of the data'},{'term':'Finding','meaning':'A change supported by evidence'},{'term':'Review','meaning':'A person decides the next action'}],folderLabel='@NikBearBrown'))
def flow(bid,narr,title,labels,kinds,mode='flow',act='The Useful Idea',note='Conceptual illustration',**extra):
 return rem(bid,narr,'DesignPipelineClaim',dict(title=title,labels=labels,objectKinds=kinds,diagramStyle='show-tell-isometric',mode=mode,note=note,cues=[.10,.28,.65,.82],**extra),act=act)
flow('B01','The useful idea is to connect three things: the data, the analysis, and the evidence for a decision. A change matters because of what it affects. That makes the question part of the checking process.','Evidence Before Action',['Data','Analysis','Evidence'],['document','adapter','document'])
cap=json.loads((r/'captures/capture.json').read_text())
def capture(bid,narr,file,caption,focus,ring=None):
 image='oncosys-films/'+slug+'/'+file
 target=root.parent/'brutalist.art/runtime/remotion/public'/image;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(r/'captures'/file,target)
 move=dict(at=.22,x=focus[0],y=focus[1],scale=focus[2]);
 if ring:move['ring']=ring
 rem(bid,narr,'BrowserCapture',dict(url=cap['url'],image=image,imageAspect=16/9,caption=caption,moves=[dict(at=0,x=.5,y=.5,scale=1),move],moveSeconds=.8))
capture('B02','Here is the actual ReadySet interface, running locally with invented test data. A deliberately swapped measurement triggers a review. The headline tells us to pause, and the analysis cards tell us where to look.','overview.png','ReadySet · synthetic local demonstration · 14 Nov 2026',(.49,.34,1.4))
capture('B03','Now the question changes. We leave out the affected protein analysis and keep the unrelated analysis. In this tested example, the verdict becomes Ready. That is a concrete demonstration of question-dependent checking.','question-a2.png','Actual A2-only result · synthetic data',(.49,.30,1.5))
capture('B04','Bring the affected analysis back, and the finding returns. This evidence view is a strength: the reader can inspect what changed, consider the suggested repair, and see the limits of the explanation.','evidence.png','Actual finding and evidence · synthetic data',(.50,.45,1.3))
flow('B05','The next strength is the handoff. Detection produces a finding; a person reviews it before deciding on action. The normal named-review path worked in our browser checks. That makes the decision inspectable.','Keep The Human Handoff',['Finding','Review','Action'],['document','monitor','package'])
flow('B06','Next steps can build on that foundation. Add an input-validity gate before comparing changes. If required evidence is missing, the process should stop there and explain what is needed to continue.','Next: Validate Inputs',['Inputs','Validity','Comparison'],['document','scanner','adapter'],mode='gate',act='Build On The Foundation',gateLabel='Request evidence',note='Proposed next step · not a completed feature')
flow('B07','Then preserve each review as an event. A decision can change, but its earlier evidence and reasoning should remain inspectable. This is a practical extension of the evidence fingerprints the project already uses.','Next: Preserve Decisions',['Evidence','Decision','History'],['document','monitor','package'],act='Build On The Foundation',note='Proposed next step · immutable review events')
flow('B08','For the team, the opportunity is clear: keep the efficient detector and the readable evidence, then strengthen those boundaries. This is a promising research prototype. The demonstration does not establish clinical or production readiness.','An Inspectable Workflow',['Detect','Explain','Improve'],['scanner','document','adapter'],act='Build On The Foundation',note='Research prototype · detailed review linked with this film')
lines=['Connect changes to the selected analysis.','Let people inspect the evidence.','Validate inputs before interpreting changes.','Preserve the history of human decisions.']
rem('BVDT',"Let's recap with Claude. "+' '.join(lines),'ClaudeVerdictArtifact',dict(artifactTitle='ReadySet',artifactHeading='What To Build On',artifactLines=lines,lectureLayout=True,brandLabel='@NikBearBrown'),act='Recap',lead_silence_s=.5)
prompt='Help me extend ReadySet with an input-validity gate. Use invented data. Show one valid unchanged release and one missing-input case. Explain the expected decision and the evidence needed to justify it.'
rem('BHTF',prompt,'ClaudeComposerAsk',dict(greeting='Your turn.',topic='CLAUDE · YOUR TURN',segment='Test The Boundary',command=prompt,runningText='Suggested prompt — not an executed agent response',output=['Check: valid and missing inputs remain distinct.','Check: every decision points to evidence.'],folderLabel='@NikBearBrown',modelLabel='Your chosen model',effortLabel='Review',largeText=True),act='Your Turn')
rem('BOUT',title+'. At Nik Bear Brown.','ClaudeTitleOutro',dict(title=title,slug=slug,handle='@NikBearBrown',subline=''),act='Outro',kind='outro_voice',tail_silence_s=1)
